const { Scene, PerspectiveCamera, TorusKnotGeometry, Mesh, MeshBasicMaterial } = THREE

setPortCount(0, 0)
setVideoCount(1, 1)

const scene = new Scene()
const camera = new PerspectiveCamera(75, width / height, 0.1, 1000)

camera.position.z = 2.5

// No lights needed for MeshBasicMaterial

const geometry = new TorusKnotGeometry(0.8, 0.25, 150, 20)

// MeshBasicMaterial does not respond to lights and just renders the texture/color
const material = new MeshBasicMaterial({
  color: 0xffffff
})

const shape = new Mesh(geometry, material)
scene.add(shape)

function draw(t) {
  // Get texture from video inlet 0
  const tex = getTexture(0)
  if (tex) {
    material.map = tex
    material.needsUpdate = true
  }

  // Complex rotation
  shape.rotation.x = t * 0.0005
  shape.rotation.y = t * 0.0008
  shape.rotation.z = t * 0.0003

  // Subtle pulsing effect
  const scale = 1 + Math.sin(t * 0.02) * 0.1
  shape.scale.set(scale, scale, scale)

  renderer.render(scene, camera)
}
